use lsp_types::{Diagnostic, DiagnosticSeverity, DocumentSymbol, Position, Range, SymbolKind};
use tree_sitter::{Node, Parser, Tree};
use tree_sitter_language::LanguageFn;

extern "C" {
    fn tree_sitter_denotate() -> *const ();
}

pub fn parser() -> Parser {
    let mut parser = Parser::new();
    // Generated by the pinned CLI and compiled by this crate's build script.
    let language = unsafe { LanguageFn::from_raw(tree_sitter_denotate) };
    parser
        .set_language(&language.into())
        .expect("compatible generated grammar");
    parser
}

/// Source text is authoritative. Tree-sitter byte/point columns are NOT LSP
/// UTF-16 columns, and lone CR is also a line break in the editor protocol.
pub struct Document {
    pub text: String,
    pub version: i32,
    pub open: bool,
    pub tree: Tree,
    lines: Vec<usize>,
}

impl Document {
    pub fn new(parser: &mut Parser, text: String, version: i32, open: bool) -> Self {
        // B1 deliberately parses afresh. Old-tree edits/reuse are the B4 exercise.
        let tree = parser.parse(&text, None).expect("uncancelled parse");
        let mut lines = vec![0];
        let bytes = text.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i] == b'\r' {
                i += 1;
                if bytes.get(i) == Some(&b'\n') {
                    i += 1;
                }
                lines.push(i);
            } else if bytes[i] == b'\n' {
                i += 1;
                lines.push(i);
            } else {
                i += 1;
            }
        }
        Self {
            text,
            version,
            open,
            tree,
            lines,
        }
    }

    pub fn position(&self, byte: usize) -> Position {
        let line = self.lines.partition_point(|start| *start <= byte) - 1;
        Position::new(
            line as u32,
            self.text[self.lines[line]..byte].encode_utf16().count() as u32,
        )
    }

    fn range(&self, node: Node<'_>) -> Range {
        Range::new(
            self.position(node.start_byte()),
            self.position(node.end_byte()),
        )
    }

    pub fn diagnostics(&self) -> Vec<Diagnostic> {
        let mut result = Vec::new();
        self.visit_errors(self.tree.root_node(), &mut result);
        result
    }

    fn visit_errors(&self, node: Node<'_>, result: &mut Vec<Diagnostic>) {
        // Tree-sitter's reserved set applies to its `identifier` word token,
        // not the separate lowercase `constant` token. Enforce the same lexical
        // restriction here, before semantic analysis (including declarations).
        let reserved_constant = node.kind() == "constant"
            && matches!(
                &self.text[node.byte_range()],
                "module" | "use" | "sort" | "const" | "relation" | "input"
            );
        if node.is_error() || node.is_missing() || reserved_constant {
            result.push(Diagnostic {
                range: self.range(node),
                severity: Some(DiagnosticSeverity::ERROR),
                source: Some("denotate-syntax".into()),
                message: if reserved_constant {
                    format!(
                        "Reserved word '{}' cannot be a constant.",
                        &self.text[node.byte_range()]
                    )
                } else if node.is_missing() {
                    format!("Expected {}.", node.kind())
                } else {
                    "Unexpected syntax.".into()
                },
                ..Diagnostic::default()
            });
            // One diagnostic per error region, rather than every descendant.
            return;
        }
        for child in node.children(&mut node.walk()) {
            self.visit_errors(child, result);
        }
    }

    pub fn symbols(&self) -> Vec<DocumentSymbol> {
        let mut result = Vec::new();
        self.collect_symbols(self.tree.root_node(), &mut result);
        result
    }

    fn collect_symbols(&self, parent: Node<'_>, result: &mut Vec<DocumentSymbol>) {
        for node in parent.named_children(&mut parent.walk()) {
            let kind = match node.kind() {
                "module" | "import" => SymbolKind::MODULE,
                "sort" => SymbolKind::CLASS,
                "constants" => SymbolKind::CONSTANT,
                "relation" => SymbolKind::FUNCTION,
                "statement" => SymbolKind::OPERATOR,
                "ERROR" => {
                    self.collect_symbols(node, result);
                    continue;
                }
                _ => continue,
            };
            let selection = if node.kind() == "statement" {
                node.child_by_field_name("head")
                    .and_then(|head| head.child_by_field_name("name"))
            } else {
                node.child_by_field_name("name")
            };
            let Some(selection) = selection.filter(|n| !n.is_missing()) else {
                continue;
            };
            let mut tokens = Vec::new();
            self.tokens(node, &mut tokens);
            let body = tokens.iter().position(|token| *token == ":-");
            if let Some(index) = body {
                tokens.truncate(index);
            }
            tokens.retain(|token| *token != ";" && *token != "\u{feff}");
            let mut label = String::new();
            for (i, token) in tokens.iter().enumerate() {
                if i > 0 && !matches!(*token, "(" | ")" | "," | ":") && tokens[i - 1] != "(" {
                    label.push(' ');
                }
                label.push_str(token);
            }
            if body.is_some() {
                label.push_str(" :- …");
            }
            #[allow(deprecated)]
            result.push(DocumentSymbol {
                name: label,
                detail: None,
                kind,
                tags: None,
                deprecated: None,
                range: if node.kind() == "module" {
                    self.range(selection)
                } else {
                    self.range(node)
                },
                selection_range: self.range(selection),
                children: None,
            });
        }
    }

    fn tokens<'a>(&'a self, node: Node<'_>, tokens: &mut Vec<&'a str>) {
        if node.kind() == "comment" || node.is_missing() {
            return;
        }
        if node.child_count() == 0 {
            tokens.push(&self.text[node.byte_range()]);
        } else {
            for child in node.children(&mut node.walk()) {
                self.tokens(child, tokens);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;
    use std::{fs, path::Path};

    #[test]
    fn shared_syntax_manifest() {
        let fixtures = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures");
        let manifest: Value =
            serde_json::from_str(&fs::read_to_string(fixtures.join("syntax.json")).unwrap())
                .unwrap();
        let mut parser = parser();
        let mut failures = Vec::new();
        for case in manifest["cases"].as_array().unwrap() {
            let file = case["file"].as_str().unwrap();
            let text = fs::read_to_string(fixtures.join(file)).unwrap();
            let doc = Document::new(&mut parser, text, 1, true);
            if doc.diagnostics().is_empty() != (case["base"] == "accept") {
                failures.push(format!(
                    "{file}: expected {}\n{}\n{:?}",
                    case["base"],
                    doc.tree.root_node().to_sexp(),
                    doc.diagnostics()
                ));
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
        assert_eq!(manifest["cases"].as_array().unwrap().len(), 65);
    }

    #[test]
    fn reserved_constants_in_each_position_and_keyword_prefixes() {
        let mut parser = parser();
        for word in ["module", "use", "sort", "const", "relation", "input"] {
            for suffix in ["", "_value"] {
                let name = format!("{word}{suffix}");
                for statement in [
                    format!("const {name}: S;"),
                    format!("r({name});"),
                    format!("r(X) :- r({name});"),
                    format!("r(X) :- !r({name});"),
                ] {
                    let text = format!("module example; sort S; relation r(value: S); {statement}");
                    let doc = Document::new(&mut parser, text, 1, true);
                    let diagnostics = doc.diagnostics();
                    if suffix.is_empty() {
                        assert_eq!(diagnostics.len(), 1, "{statement}");
                        assert!(
                            diagnostics[0].message.contains("Reserved word"),
                            "{statement}"
                        );
                        let start = doc.text.rfind(word).unwrap();
                        assert_eq!(
                            diagnostics[0].range,
                            Range::new(doc.position(start), doc.position(start + word.len()))
                        );
                    } else {
                        assert!(diagnostics.is_empty(), "{statement}: {diagnostics:?}");
                    }
                }
            }
        }
    }

    #[test]
    fn utf16_positions_and_line_endings() {
        let text = "// 🦀\r\nsort Slot;\rsort Source;\n";
        let doc = Document::new(&mut parser(), text.into(), 1, true);
        assert_eq!(doc.position("// 🦀".len()), Position::new(0, 5));
        assert_eq!(
            doc.position(text.find("Slot").unwrap()),
            Position::new(1, 5)
        );
        assert_eq!(
            doc.position(text.find("Source").unwrap()),
            Position::new(2, 5)
        );
    }
}
